sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
sources=['research678_core.py','research678_run.py','research678_render.py','research678_init.py','test_research678.py','study005_core.py','study005_run.py','scripts/model_strategy_study.py','scripts/render_strategy_maps.py','scripts/verify_app.py','scripts/build_runtime.py','artifacts/interpretability/study-005-final/matched-relocations005.json']+[str(p.relative_to(ROOT)) for p in sorted((ROOT/'falken9').glob('*.py'))]
contracts={
'006':dict(title='Router usefulness',cap='28 runs: actual, joint reverse, assignment swap, actual uniform; six memberships x3 gate modes; two natural donor contracts x3 modes',pair_memberships=[[0,1],[0,2],[0,3],[1,2],[1,3],[2,3]],gates=['native receiver pair renormalization','receiver actual slot gates, pair ordered by scores','uniform16384/16384'],natural_donors='lowest ID other board within same fold/ply/side/own-opponent corner-edge-center counts; alternative membership or identical ordered routes/different gates; no matching relaxation',selection='training only minimize fixed-pair chosen errors, then set changes, then lexicographic pair; confirmation untouched',task_controls='has_win/must_block/has_fork positives vs same-fold/ply/geometry neutral, lowest ID; report support/reuse/empty strata',offline_compute='all4 experts627 boards2508 vs normal1254; normally unselected outputs are additional counterfactual compute'),
'007':dict(title='Bounded pathway sufficiency',scope='Post-route entire expert output vector only; receiver readout residual, router/gates, native mixture rounding and final head retained',selection='train-only max active must_block minus neutral zero-output error-rate difference across4 expert IDs; tie lowest; cyclic next expert control',matching='frozen study005 relocation inventory; same raw candidate/ply/side/geometry/fold; candidate active both; gate Linf<=4096; ordered-route same vs changed separate; first24/task/fold/role/contract; never relax',directions='both receiver<-donor and donor<-receiver',variants=['identity','candidate-donor','noncandidate-natural-shared','all-shared-natural','candidate-restore','zero-noncandidate','zero-all-selected','candidate-restore-from-zero'],cap='max36 strata x24 pairs x2 directions x8 variants; plus4 expert-zero necessity evaluations',claim_boundary='local rescue/preservation/necessity not full circuit sufficiency or natural mediation; unshared unselected donors unavailable, not zero'),
'008':dict(title='Exact integer decision-fragility',coordinates='all9 output.bias; all4 router.bias; all16 norm2.weight;9 output.weight rows at training-max meanabs merged unit, low-unit ties',cap='38 coordinates x +/-1 =76 attempts; reject descriptor/code boundary, do not replace; per accepted mutation exact full network then original-code restoration all stages',selection='training activation only; no test fragility selection',boundary='>=0 membership; negative->nonnegative vs nonnegative->negative, occupied/legal masking separate; integer flip distance y+1 if y>=0 else -y',claim_boundary='local one-code panel only, not quantization conversion or human strategy')}
for stage,design in contracts.items():
    p=ROOT/f'experiment-study{stage}.json';assert not p.exists(),p
    m=dict(study=stage,design=design,source_sha256={n:sha(ROOT/n) for n in sources},baseline_sha256=sha(ROOT/'baseline-study006-008.json'),preservation_manifest_sha256=sha(ROOT/'preservation-before006-008.json'),frozen_before_confirmation=True,common=dict(model_sha256='fe180f8a931f9d92d8aa39da337bc819d0dbe4e6d971edcba00324fbc18a91c1',folds=[372,121,134],novel_domain_generalization=False,training=False,target_benchmark=False,controls='baseline/noop first; restoration; exact complete set/legal/raw tie; empty vs nonoptimal nonempty vs optimal tie separated',no_posthoc_relaxation=True))
    p.write_text(json.dumps(m,indent=2,sort_keys=True)+'\n');print(stage,sha(p))
